import os
import stat
import tempfile
import hashlib
import hmac
import json
import time
from pathlib import Path
from typing import Optional, Dict, Tuple

class SecureFileStore:
    """Secure file storage with integrity verification and access control."""

    def __init__(self, base_dir: str, secret_key: bytes):
        self.base_dir = os.path.realpath(base_dir)
        self.secret_key = secret_key
        self._ensure_base_dir()

    def _ensure_base_dir(self):
        os.makedirs(self.base_dir, mode=0o700, exist_ok=True)

    def _compute_mac(self, data: bytes) -> str:
        return hmac.new(self.secret_key, data, hashlib.sha256).hexdigest()

    def _resolve_path(self, filename: str) -> Optional[str]:
        """Safely resolve filename to prevent directory traversal."""
        # Reject any path separators or null bytes
        if '/' in filename or '\\' in filename or '\x00' in filename:
            return None
        if filename.startswith('.') or filename == '':
            return None
        # Only allow alphanumeric, dash, underscore, dot
        if not all(c.isalnum() or c in '-_.' for c in filename):
            return None
        full_path = os.path.join(self.base_dir, filename)
        # Verify resolved path is within base_dir
        real_path = os.path.realpath(full_path)
        if not real_path.startswith(self.base_dir + os.sep):
            return None
        return full_path

    def _open_file_safely(self, filepath: str, flags: int, mode: int = 0o600) -> Optional[int]:
        """Open file atomically with O_NOFOLLOW to prevent symlink attacks."""
        try:
            fd = os.open(filepath, flags | os.O_NOFOLLOW, mode)
            # Verify ownership after opening
            fd_stat = os.fstat(fd)
            if fd_stat.st_uid != os.getuid():
                os.close(fd)
                return None
            if fd_stat.st_mode & (stat.S_IROTH | stat.S_IWOTH):
                os.close(fd)
                return None
            return fd
        except OSError:
            return None

    def store_file(self, filename: str, data: bytes, metadata: Optional[Dict] = None) -> bool:
        """Store a file with integrity MAC."""
        filepath = self._resolve_path(filename)
        if filepath is None:
            return False

        try:
            mac = self._compute_mac(data)
            # Write data file atomically with O_NOFOLLOW
            fd = os.open(filepath, os.O_WRONLY | os.O_CREAT | os.O_TRUNC | os.O_NOFOLLOW, 0o600)
            try:
                os.write(fd, data)
            finally:
                os.close(fd)

            # Write metadata
            meta = {
                'mac': mac,
                'size': len(data),
                'created': time.time(),
                'metadata': metadata or {}
            }
            meta_path = filepath + '.meta'
            fd = os.open(meta_path, os.O_WRONLY | os.O_CREAT | os.O_TRUNC | os.O_NOFOLLOW, 0o600)
            try:
                os.write(fd, json.dumps(meta).encode())
            finally:
                os.close(fd)
            return True
        except OSError:
            return False

    def read_file(self, filename: str) -> Optional[Tuple[bytes, Dict]]:
        """Read a file with integrity verification.

        Uses O_NOFOLLOW to atomically prevent symlink-based attacks.
        """
        filepath = self._resolve_path(filename)
        if filepath is None:
            return None

        # Open with O_NOFOLLOW - atomic symlink protection
        fd = self._open_file_safely(filepath, os.O_RDONLY)
        if fd is None:
            return None
        try:
            data = b''
            while True:
                chunk = os.read(fd, 65536)
                if not chunk:
                    break
                data += chunk
        finally:
            os.close(fd)

        # Read and verify metadata
        meta_path = filepath + '.meta'
        meta_fd = self._open_file_safely(meta_path, os.O_RDONLY)
        if meta_fd is None:
            return None
        try:
            meta_raw = b''
            while True:
                chunk = os.read(meta_fd, 65536)
                if not chunk:
                    break
                meta_raw += chunk
        finally:
            os.close(meta_fd)

        try:
            meta = json.loads(meta_raw)
        except (json.JSONDecodeError, ValueError):
            return None

        # Verify integrity
        expected_mac = meta.get('mac', '')
        actual_mac = self._compute_mac(data)
        if not hmac.compare_digest(expected_mac, actual_mac):
            return None

        return (data, meta.get('metadata', {}))

    def delete_file(self, filename: str) -> bool:
        """Securely delete a file using atomic checks."""
        filepath = self._resolve_path(filename)
        if filepath is None:
            return False

        # Use lstat to check without following symlinks
        try:
            file_stat = os.lstat(filepath)
            if stat.S_ISLNK(file_stat.st_mode):
                return False
            if file_stat.st_uid != os.getuid():
                return False
            os.unlink(filepath)
            meta_path = filepath + '.meta'
            try:
                os.unlink(meta_path)
            except OSError:
                pass
            return True
        except OSError:
            return False

    def list_files(self) -> list:
        """List all stored files."""
        try:
            entries = os.listdir(self.base_dir)
            return [e for e in entries if not e.endswith('.meta') and not e.startswith('.')]
        except OSError:
            return []
